const binary = $input.first().binary?.configFile;
if (!binary?.data) {
  throw new Error('config.json is missing or empty');
}

const content = Buffer.from(binary.data, 'base64').toString('utf8');
let config;
try {
  config = JSON.parse(content);
} catch (error) {
  throw new Error(`Invalid JSON in config.json: ${error.message}`);
}

const required = ['enabled', 'min_running', 'region', 'tag_filter', 'scale_out', 'scale_in'];
for (const key of required) {
  if (!(key in config)) throw new Error(`Missing config key: ${key}`);
}

return [{ json: config }];

const AWS = require('aws-sdk');
const fs = require('fs');

const config = $input.first().json;
const now = new Date();
const nowIso = now.toISOString();
const logPath = '/opt/ec2-autoscaler/logs/autoscaler.log';
const statePath = '/opt/ec2-autoscaler/state.json';

function asNumber(value, name) {
  const num = Number(value);
  if (!Number.isFinite(num)) throw new Error(`Config field ${name} must be a number`);
  return num;
}

function isTrueTag(value) {
  return String(value || '').toLowerCase() === 'true';
}

function tagsToMap(tags) {
  const map = {};
  for (const tag of tags || []) {
    map[tag.Key] = tag.Value;
  }
  return map;
}

function loadState() {
  try {
    const raw = fs.readFileSync(statePath, 'utf8');
    const parsed = JSON.parse(raw);
    return {
      last_start_at: parsed.last_start_at || null,
      last_stop_at: parsed.last_stop_at || null
    };
  } catch (_) {
    return { last_start_at: null, last_stop_at: null };
  }
}

function saveState(state) {
  fs.writeFileSync(statePath, JSON.stringify(state, null, 2));
}

function cooldownPassed(lastIso, cooldownMinutes) {
  if (!lastIso) return true;
  const diffMs = now.getTime() - new Date(lastIso).getTime();
  return diffMs >= cooldownMinutes * 60 * 1000;
}

async function listInstancesByState(ec2, stateName, tagFilter) {
  const Filters = [
    { Name: 'instance-state-name', Values: [stateName] },
    ...Object.entries(tagFilter || {}).map(([k, v]) => ({ Name: `tag:${k}`, Values: [String(v)] }))
  ];

  let NextToken;
  const instances = [];

  do {
    const resp = await ec2.describeInstances({ Filters, NextToken }).promise();
    for (const reservation of resp.Reservations || []) {
      for (const instance of reservation.Instances || []) {
        instances.push(instance);
      }
    }
    NextToken = resp.NextToken;
  } while (NextToken);

  return instances;
}

async function getCpuAverage(cw, instanceId, windowMinutes, periodSeconds = 300) {
  const end = now;
  const start = new Date(now.getTime() - windowMinutes * 60 * 1000);

  const resp = await cw.getMetricStatistics({
    Namespace: 'AWS/EC2',
    MetricName: 'CPUUtilization',
    Dimensions: [{ Name: 'InstanceId', Value: instanceId }],
    StartTime: start,
    EndTime: end,
    Period: periodSeconds,
    Statistics: ['Average']
  }).promise();

  const points = (resp.Datapoints || []).map(p => p.Average).filter(v => typeof v === 'number');
  if (!points.length) return null;
  return points.reduce((a, b) => a + b, 0) / points.length;
}

function appendLog(line) {
  fs.mkdirSync('/opt/ec2-autoscaler/logs', { recursive: true });
  fs.appendFileSync(logPath, `${line}\n`);
}

if (!config.enabled) {
  const msg = `[${nowIso}] SKIP enabled=false`;
  appendLog(msg);
  return [{ json: { status: 'skipped', reason: 'enabled=false', message: msg } }];
}

const region = process.env.AWS_REGION || config.region;
if (!region) throw new Error('AWS region is not set in config.region or AWS_REGION env');

AWS.config.update({
  region,
  accessKeyId: process.env.AWS_ACCESS_KEY_ID,
  secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY
});

const ec2 = new AWS.EC2({ region });
const cw = new AWS.CloudWatch({ region });
const state = loadState();

const minRunning = asNumber(config.min_running, 'min_running');
const startCount = asNumber(config.scale_out.start_count ?? 1, 'scale_out.start_count');
const stopCount = asNumber(config.scale_in.stop_count ?? 1, 'scale_in.stop_count');

const runningInstances = await listInstancesByState(ec2, 'running', config.tag_filter);
const runningWithTags = runningInstances.map(i => ({
  id: i.InstanceId,
  tags: tagsToMap(i.Tags)
}));

const runningCount = runningWithTags.length;
const runningCpuForScaleOut = [];
for (const inst of runningWithTags) {
  const cpu = await getCpuAverage(cw, inst.id, asNumber(config.scale_out.window_minutes, 'scale_out.window_minutes'));
  if (cpu !== null) runningCpuForScaleOut.push({ id: inst.id, cpu });
}

const avgCpu = runningCpuForScaleOut.length
  ? runningCpuForScaleOut.reduce((a, b) => a + b.cpu, 0) / runningCpuForScaleOut.length
  : 0;
const maxCpu = runningCpuForScaleOut.length
  ? Math.max(...runningCpuForScaleOut.map(x => x.cpu))
  : 0;

let startedIds = [];
let stoppedIds = [];

const scaleOutCondition = (
  avgCpu > asNumber(config.scale_out.avg_cpu_threshold, 'scale_out.avg_cpu_threshold') ||
  maxCpu > asNumber(config.scale_out.max_cpu_threshold, 'scale_out.max_cpu_threshold')
);

if (scaleOutCondition && cooldownPassed(state.last_start_at, asNumber(config.scale_out.cooldown_minutes, 'scale_out.cooldown_minutes'))) {
  const stoppedInstances = await listInstancesByState(ec2, 'stopped', config.tag_filter);
  const sortable = stoppedInstances.map(i => {
    const tags = tagsToMap(i.Tags);
    const rawPriority = Number(tags.Priority);
    const priority = Number.isFinite(rawPriority) ? rawPriority : 999;
    return { id: i.InstanceId, priority };
  });

  sortable.sort((a, b) => a.priority - b.priority || a.id.localeCompare(b.id));
  startedIds = sortable.slice(0, startCount).map(x => x.id);

  if (startedIds.length > 0) {
    await ec2.startInstances({ InstanceIds: startedIds }).promise();
    state.last_start_at = nowIso;
  }
}

const stopCooldownPassed = cooldownPassed(state.last_stop_at, asNumber(config.scale_in.cooldown_minutes, 'scale_in.cooldown_minutes'));
if (runningCount > minRunning && stopCooldownPassed) {
  const stopCandidates = [];
  for (const inst of runningWithTags) {
    if (isTrueTag(inst.tags.NeverStop)) continue;
    const idleCpu = await getCpuAverage(cw, inst.id, asNumber(config.scale_in.window_minutes, 'scale_in.window_minutes'));
    if (idleCpu === null) continue;
    if (idleCpu < asNumber(config.scale_in.cpu_threshold, 'scale_in.cpu_threshold')) {
      stopCandidates.push({ id: inst.id, cpu: idleCpu });
    }
  }

  stopCandidates.sort((a, b) => a.cpu - b.cpu || a.id.localeCompare(b.id));
  const maxAllowedStops = Math.max(0, runningCount - minRunning);
  const toStop = Math.min(stopCount, maxAllowedStops);
  stoppedIds = stopCandidates.slice(0, toStop).map(x => x.id);

  if (stoppedIds.length > 0) {
    await ec2.stopInstances({ InstanceIds: stoppedIds }).promise();
    state.last_stop_at = nowIso;
  }
}

saveState(state);

const report = `[${nowIso}] region=${region} running=${runningCount} avgCPU=${avgCpu.toFixed(2)} maxCPU=${maxCpu.toFixed(2)} started=${startedIds.join(',') || '-'} stopped=${stoppedIds.join(',') || '-'}`;
appendLog(report);

return [{
  json: {
    status: 'ok',
    timestamp: nowIso,
    region,
    running_count: runningCount,
    avg_cpu: Number(avgCpu.toFixed(2)),
    max_cpu: Number(maxCpu.toFixed(2)),
    started_instances: startedIds,
    stopped_instances: stoppedIds,
    report
  }
}];
